@import url('https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600;700;800&family=Space+Grotesk:wght@500;600;700&display=swap');
:root{--bg:#100d18;--panel:#191522;--panel2:#211b2c;--line:#342b41;--text:#f7f1f8;--muted:#a79bad;--red:#ff4e70;--gold:#ffca72;--mint:#73e4bd;--purple:#b99aff;--blue:#85c9ff;--radius:18px}*{box-sizing:border-box}body{margin:0;background:radial-gradient(ellipse at 85% -15%,#39203a 0,transparent 42%),var(--bg);color:var(--text);font-family:'DM Sans',sans-serif;min-height:100vh}button{font:inherit;color:inherit;cursor:pointer}button:focus-visible{outline:2px solid var(--gold);outline-offset:3px}.app-shell{max-width:1320px;margin:auto;padding:0 28px 100px}.topbar{height:76px;display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid #ffffff12}.brand{border:0;background:none;display:flex;gap:11px;align-items:center;font:700 15px 'Space Grotesk';letter-spacing:.13em}.brand b{color:var(--red)}.brand-mark{display:grid;place-items:center;width:34px;height:34px;border-radius:11px;background:linear-gradient(145deg,#ff7187,#be4b92);color:white;font-size:21px;box-shadow:0 6px 25px #ff4e7033}.top-status{display:flex;gap:14px;align-items:center;font-size:13px}.format-pill{border:1px solid var(--line);border-radius:99px;color:var(--muted);padding:7px 11px;font-size:10px;font-weight:800;letter-spacing:.09em}.wallet{color:var(--gold);font-size:15px}.wallet b{color:var(--text);margin-left:4px}.avatar{border:1px solid #ffffff27;background:#33273b;width:35px;height:35px;border-radius:50%;font-weight:800}.bottom-nav{position:fixed;z-index:5;bottom:0;left:0;right:0;display:flex;justify-content:center;gap:8px;padding:10px 12px calc(10px + env(safe-area-inset-bottom));background:#130f1bee;border-top:1px solid #ffffff16;backdrop-filter:blur(16px)}.nav-item{min-width:76px;border:0;background:transparent;color:var(--muted);display:grid;justify-items:center;gap:3px;font-size:10px;padding:4px 12px;border-radius:13px}.nav-item span{font-size:20px;line-height:1}.nav-item.active{color:var(--text);background:#ffffff0c}.nav-item.active span{color:var(--red)}main{padding-top:27px}.eyebrow{font-size:10px;font-weight:800;letter-spacing:.18em;color:var(--red);text-transform:uppercase}.hero{display:grid;grid-template-columns:1.3fr .7fr;min-height:220px;border:1px solid #ffffff10;border-radius:24px;padding:30px 34px;background:linear-gradient(110deg,#291a30 0%,#20192d 52%,#3b1c34 100%);overflow:hidden;position:relative}.hero:after{content:'✦';position:absolute;right:12%;top:-90px;font-size:330px;color:#ff76800c;pointer-events:none}.hero h1{font:700 clamp(32px,5vw,55px)/1.02 'Space Grotesk';letter-spacing:-.05em;margin:12px 0}.hero p{color:#c3b4ca;max-width:500px;line-height:1.55;margin:10px 0 20px;font-size:14px}.hero-art{align-self:center;justify-self:center;font-size:112px;filter:drop-shadow(0 12px 35px #ff497a52);transform:rotate(-9deg)}.button{border:1px solid transparent;border-radius:12px;padding:11px 16px;font-weight:800;font-size:12px;transition:.18s}.button:hover{transform:translateY(-1px);filter:brightness(1.08)}.button.primary{background:var(--red);color:#210e1a;box-shadow:0 6px 20px #ff4e7030}.button.secondary{background:#ffffff0b;border-color:#ffffff1a}.button.gold{background:var(--gold);color:#241729}.button.small{padding:8px 11px;font-size:11px}.section-heading{display:flex;justify-content:space-between;align-items:end;margin:28px 0 14px}.section-heading h2{font:600 19px 'Space Grotesk';margin:0}.section-heading p{margin:5px 0 0;color:var(--muted);font-size:12px}.text-button{border:0;background:none;color:var(--gold);font-size:12px;font-weight:800}.mode-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:12px}.mode-card{min-height:102px;text-align:left;background:var(--panel);border:1px solid var(--line);border-radius:15px;padding:15px;position:relative;overflow:hidden}.mode-card:hover,.mode-card.selected{border-color:var(--red);background:linear-gradient(140deg,#2c1c30,#191522)}.mode-card.selected:after{content:'✓';position:absolute;right:12px;top:11px;color:var(--mint);font-weight:bold}.mode-title{font:600 14px 'Space Grotesk';display:block;padding-right:15px}.mode-sub{display:block;color:var(--muted);font-size:11px;margin-top:8px}.mode-icon{color:var(--red);font-size:19px;margin-bottom:8px}.feature-row{display:grid;grid-template-columns:1.2fr 1fr 1fr;gap:13px}.feature-card{background:var(--panel);border:1px solid var(--line);padding:18px;border-radius:16px;min-height:140px;display:flex;flex-direction:column;justify-content:space-between}.feature-card h3{margin:0;font:600 16px 'Space Grotesk'}.feature-card p{color:var(--muted);font-size:12px;line-height:1.45;margin:7px 0 14px}.feature-top{display:flex;justify-content:space-between}.feature-icon{font-size:25px}.tag{font-size:9px;font-weight:800;color:var(--mint);letter-spacing:.09em;text-transform:uppercase}.row{display:flex;align-items:center;gap:9px}.page-title{font:700 34px 'Space Grotesk';margin:4px 0 6px;letter-spacing:-.04em}.page-intro{color:var(--muted);margin:0 0 22px;font-size:13px}.shop-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:14px}.shop-card{background:var(--panel);border:1px solid var(--line);border-radius:17px;padding:18px;display:flex;flex-direction:column;min-height:220px}.shop-card h3{font:600 16px 'Space Grotesk';margin:0}.shop-card p{color:var(--muted);font-size:12px;line-height:1.5;flex:1}.shop-card .price{color:var(--gold);font-size:13px;font-weight:800}.shop-icon{height:55px;display:flex;align-items:center;font-size:35px}.shop-card .button{width:100%;margin-top:12px}.shop-category{font-size:10px;color:var(--red);font-weight:800;letter-spacing:.14em;text-transform:uppercase;margin-bottom:8px}.tabs{display:flex;gap:7px;overflow:auto;margin:16px 0}.tab{white-space:nowrap;background:#ffffff08;border:1px solid #ffffff12;border-radius:99px;color:var(--muted);padding:8px 13px;font-size:11px;font-weight:700}.tab.active{background:#ff4e7020;border-color:#ff4e7060;color:#ff8c9f}.cards-grid{display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:13px}.tcg-card{border:1px solid #ffffff1b;border-radius:15px;background:#1a1522;overflow:hidden;cursor:pointer;transition:transform .18s,border-color .18s;position:relative}.tcg-card:hover{transform:translateY(-4px);border-color:#ff778e}.card-art{height:135px;display:flex;justify-content:center;align-items:center;position:relative;overflow:hidden;background:linear-gradient(145deg,var(--c1),var(--c2))}.card-art:before,.card-art:after{content:'';position:absolute;border:1px solid #ffffff32;border-radius:50%;width:115px;height:115px;transform:rotate(35deg) scaleX(.55)}.card-art:after{width:145px;height:145px;transform:rotate(-24deg) scaleX(.48)}.card-emoji{font-size:65px;filter:drop-shadow(0 8px 6px #160b1c85);z-index:1}.card-rarity{position:absolute;top:9px;left:9px;font-size:8px;font-weight:800;letter-spacing:.08em;padding:4px 6px;border-radius:5px;background:#100d18b8}.card-cost{position:absolute;right:9px;top:9px;width:23px;height:23px;border:1px solid #ffffff6b;background:#130f1dcc;border-radius:50%;display:grid;place-items:center;font-size:10px;font-weight:800}.card-copy{padding:11px}.card-name{font:600 13px 'Space Grotesk';white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.card-sub{color:var(--muted);font-size:9px;margin-top:4px}.card-stats{display:flex;justify-content:space-between;border-top:1px solid #ffffff14;margin-top:9px;padding-top:8px;color:#e3d8e6;font-size:9px;font-weight:700}.card-stats span:first-child{color:var(--red)}.card-qty{position:absolute;right:8px;bottom:8px;border-radius:99px;background:var(--mint);color:#10221c;padding:3px 6px;font-size:9px;font-weight:900}.deck-layout{display:grid;grid-template-columns:1.1fr .9fr;gap:16px}.box{background:var(--panel);border:1px solid var(--line);border-radius:17px;padding:18px}.box h3{font:600 16px 'Space Grotesk';margin:0 0 8px}.deck-meter{display:flex;justify-content:space-between;color:var(--muted);font-size:12px;margin:17px 0 7px}.progress{height:7px;border-radius:99px;background:#ffffff12;overflow:hidden}.progress span{height:100%;display:block;background:linear-gradient(90deg,var(--red),#ffae79);border-radius:99px}.deck-row{display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid #ffffff0f;padding:10px 0;font-size:12px}.deck-row:last-child{border:0}.deck-row small{color:var(--muted)}.counter{display:flex;align-items:center;gap:8px}.counter button{width:26px;height:26px;background:#ffffff0d;border:1px solid #ffffff1a;border-radius:8px}.battle-layout{display:grid;grid-template-columns:1fr 300px;gap:15px}.board{background:linear-gradient(145deg,#25192a,#171421);border:1px solid var(--line);border-radius:20px;padding:18px;min-height:410px}.board-head{display:flex;justify-content:space-between;color:var(--muted);font-size:11px}.bunker{display:grid;grid-template-columns:repeat(5,1fr);gap:7px;margin:14px 0}.bunker-slot{height:66px;border:1px dashed #ffffff24;border-radius:11px;display:grid;place-items:center;color:#766a7c;font-size:10px;text-align:center}.bunker-slot.filled{border-style:solid;border-color:#ff778d;color:#fff;background:#ff4e7015}.battle-controls{display:flex;gap:8px;flex-wrap:wrap;margin-top:14px}.battle-log{max-height:160px;overflow:auto;color:var(--muted);font-size:11px;line-height:1.6}.divider{height:1px;background:#ffffff12;margin:14px 0}.collection-toolbar{display:flex;justify-content:space-between;align-items:center;gap:10px}.search{background:#ffffff0a;border:1px solid var(--line);border-radius:10px;color:white;padding:10px 12px;min-width:180px}.empty{padding:26px;text-align:center;color:var(--muted);background:#ffffff05;border:1px dashed var(--line);border-radius:14px;font-size:13px}.modal-backdrop{position:fixed;z-index:20;inset:0;background:#09070dcc;display:grid;place-items:center;padding:18px;overflow:auto}.modal{width:min(720px,100%);background:#1b1624;border:1px solid #4b3b55;border-radius:20px;padding:21px;box-shadow:0 25px 100px #000b}.modal-head{display:flex;justify-content:space-between;align-items:center;margin-bottom:14px}.modal-head h2{font:600 20px 'Space Grotesk';margin:0}.close{border:0;background:#ffffff12;width:32px;height:32px;border-radius:9px}.card-detail{display:grid;grid-template-columns:220px 1fr;gap:20px}.card-detail .card-art{height:295px;border-radius:14px}.detail-text{color:#c2b5c8;font-size:13px;line-height:1.6}.detail-text h2{color:white;font:600 25px 'Space Grotesk';margin:4px 0}.detail-text .stats{color:var(--gold);font-weight:700}.modal-actions{display:flex;gap:8px;margin-top:16px;flex-wrap:wrap}.choice-row{display:flex;gap:8px;margin:14px 0}.choice{flex:1;background:#ffffff09;border:1px solid var(--line);border-radius:11px;padding:11px}.choice.selected{border-color:var(--red);color:#ff9aab}.toast{position:fixed;z-index:30;bottom:82px;left:50%;transform:translate(-50%,20px);background:#f7eff8;color:#211629;padding:10px 16px;border-radius:99px;font-size:12px;font-weight:700;opacity:0;transition:.2s;pointer-events:none}.toast.show{opacity:1;transform:translate(-50%,0)}.friday-banner{border:1px solid #ffca7255;background:#ffca720b;padding:15px;border-radius:14px;display:flex;justify-content:space-between;align-items:center;margin-top:15px}.friday-banner p{margin:3px 0 0;color:var(--muted);font-size:11px}
@media(max-width:850px){.app-shell{padding:0 17px 94px}.mode-grid{grid-template-columns:repeat(2,1fr)}.cards-grid{grid-template-columns:repeat(3,minmax(0,1fr))}.shop-grid{grid-template-columns:repeat(2,1fr)}.battle-layout{grid-template-columns:1fr 240px}.hero{padding:25px}.hero-art{font-size:82px}}
@media(max-width:600px){.app-shell{padding:0 13px 90px}.topbar{height:64px}.brand{font-size:12px}.format-pill{display:none}.top-status{gap:9px}.hero{grid-template-columns:1fr;padding:22px;min-height:235px}.hero-art{position:absolute;right:13px;bottom:12px;font-size:70px;opacity:.72}.hero-copy{position:relative;z-index:1}.hero p{max-width:75%;font-size:12px}.mode-grid{gap:8px}.mode-card{padding:12px;min-height:96px}.mode-title{font-size:12px}.mode-sub{font-size:10px}.feature-row{grid-template-columns:1fr 1fr}.feature-card:first-child{grid-column:span 2;min-height:120px}.feature-card{padding:14px;min-height:130px}.shop-grid{grid-template-columns:1fr 1fr;gap:9px}.shop-card{padding:12px;min-height:220px}.shop-card h3{font-size:13px}.shop-card p{font-size:11px}.cards-grid{grid-template-columns:repeat(2,minmax(0,1fr));gap:9px}.card-art{height:120px}.card-emoji{font-size:55px}.card-copy{padding:9px}.card-name{font-size:12px}.deck-layout{grid-template-columns:1fr}.battle-layout{grid-template-columns:1fr}.board{min-height:0;padding:13px}.bunker{gap:4px}.bunker-slot{height:54px;font-size:8px}.collection-toolbar{align-items:stretch;flex-direction:column}.search{width:100%}.card-detail{grid-template-columns:1fr}.card-detail .card-art{height:210px}.detail-text h2{font-size:21px}.bottom-nav{gap:1px}.nav-item{min-width:0;flex:1;padding:5px 2px;font-size:9px}.nav-item span{font-size:19px}.page-title{font-size:29px}.friday-banner{align-items:flex-start;gap:10px;flex-direction:column}}

const cards = [
 {id:'charlie',name:'Charlie Morningstar',series:'Hazbin Hotel',kind:'Character',emoji:'👑',colors:['#ef6684','#5b244e'],rarity:'MYTHIC',cost:3,hp:120,atk:40,text:'Bright future: Heal 20 damage from each ally in your bunker.'},
 {id:'alastor',name:'Alastor, Radio Demon',series:'Hazbin Hotel',kind:'Character',emoji:'📻',colors:['#e33d43','#441a35'],rarity:'LEGENDARY',cost:4,hp:150,atk:60,text:'Broadcast: Deal 20 damage to every opposing bunker slot.'},
 {id:'angel',name:'Angel Dust',series:'Hazbin Hotel',kind:'Character',emoji:'🕷️',colors:['#f48aa5','#713258'],rarity:'RARE',cost:2,hp:100,atk:40,text:'Spotlight: Draw a card when Angel enters your bunker.'},
 {id:'vaggie',name:'Vaggie',series:'Hazbin Hotel',kind:'Character',emoji:'🪽',colors:['#e8c1d5','#624d81'],rarity:'RARE',cost:2,hp:110,atk:50,text:'Guardian: Reduce damage to an adjacent ally by 20.'},
 {id:'husk',name:'Husk',series:'Hazbin Hotel',kind:'Character',emoji:'🃏',colors:['#b0706a','#382a4d'],rarity:'UNCOMMON',cost:1,hp:100,atk:30,text:'One more round: Flip a coin. Heads: draw 1 card.'},
 {id:'niffty',name:'Niffty',series:'Hazbin Hotel',kind:'Character',emoji:'🧹',colors:['#f78a62','#643356'],rarity:'UNCOMMON',cost:1,hp:80,atk:40,text:'Quick clean: Remove one negative effect from an ally.'},
 {id:'blitzo',name:'Blitzø',series:'Helluva Boss',kind:'Character',emoji:'🎯',colors:['#de5260','#552340'],rarity:'LEGENDARY',cost:3,hp:130,atk:50,text:'I.M.P. job: Deal 20 bonus damage if you have another ally.'},
 {id:'stolas',name:'Stolas',series:'Helluva Boss',kind:'Character',emoji:'🦉',colors:['#a576d7','#31294d'],rarity:'MYTHIC',cost:4,hp:140,atk:50,text:'Astral sight: Look at the top 3 cards of your deck; keep one.'},
 {id:'loona',name:'Loona',series:'Helluva Boss',kind:'Character',emoji:'🐺',colors:['#8891c6','#342b58'],rarity:'RARE',cost:2,hp:120,atk:50,text:'Hellhound rush: This attack ignores 20 damage reduction.'},
 {id:'moxxie',name:'Moxxie',series:'Helluva Boss',kind:'Character',emoji:'🎼',colors:['#ca5669','#412544'],rarity:'UNCOMMON',cost:1,hp:90,atk:30,text:'Careful shot: Search your hand for an energy and attach it.'},
 {id:'millie',name:'Millie',series:'Helluva Boss',kind:'Character',emoji:'🪓',colors:['#e15a68','#59233d'],rarity:'RARE',cost:2,hp:110,atk:60,text:'Whirlwind: Deal 10 damage to a second opposing character.'},
 {id:'dandy',name:'Dandy',series:"Dandy's World",kind:'Character',emoji:'🌼',colors:['#f5c46b','#68426e'],rarity:'MYTHIC',cost:3,hp:130,atk:40,text:'Wonder shop: Find a supporter card in your deck.'},
 {id:'astro',name:'Astro',series:"Dandy's World",kind:'Character',emoji:'🌙',colors:['#7896d6','#302d65'],rarity:'LEGENDARY',cost:3,hp:120,atk:50,text:'Dream dust: Inflict drowsy on the opposing active character.'},
 {id:'vee',name:'Vee',series:"Dandy's World",kind:'Character',emoji:'📺',colors:['#66c8c0','#244a62'],rarity:'RARE',cost:2,hp:100,atk:40,text:'Channel surf: Confuse the opposing active character.'},
 {id:'pebble',name:'Pebble',series:"Dandy's World",kind:'Character',emoji:'🐶',colors:['#cf977a','#593b56'],rarity:'UNCOMMON',cost:1,hp:90,atk:30,text:'Good boy: Heal 10 damage from an ally.'},
 {id:'zestial',name:'Zestial',series:'Hazbin Hotel',kind:'Character',emoji:'🕸️',colors:['#56a783','#1e3946'],rarity:'RARE',cost:3,hp:140,atk:40,text:'Ancient fear: Confuse the opposing active character.'},
 {id:'energy',name:'Infernal Energy',series:'Energy',kind:'Energy',emoji:'🔥',colors:['#ff854c','#752b43'],rarity:'COMMON',cost:0,hp:0,atk:0,text:'Attach to one of your characters once each turn to power attacks.'},
 {id:'supporter',name:'Strategic Support',series:'Trainer',kind:'Supporter',emoji:'📜',colors:['#7799d2','#29345b'],rarity:'UNCOMMON',cost:0,hp:0,atk:0,text:'Draw 2 cards. Supporters do not have a copy limit.'},
 {id:'revive',name:'Second Chance',series:'Trainer',kind:'Revive',emoji:'💫',colors:['#68cbaa','#204b4a'],rarity:'RARE',cost:0,hp:0,atk:0,text:'Revive a defeated character with 30 HP. One use per battle.'},
 {id:'effectcoin',name:'Chaos Coin',series:'Item',kind:'Item',emoji:'🪙',colors:['#e8b755','#634331'],rarity:'RARE',cost:0,hp:0,atk:0,text:'Flip after attacking: Heads applies confusion; tails applies drowsy.'}
];
const modes=[['Expanded format','Normal','expanded-normal'],['Expanded format','Ranked','expanded-ranked'],['Standard format','Ranked','standard-ranked'],['Standard format','Normal','standard-normal'],['Unrestricted format','Normal','unrestricted-normal'],['Unrestricted format','Ranked','unrestricted-ranked'],['Metal card mode','Ranked','metal-ranked'],['Metal card mode','Normal','metal-normal'],['Jumbo card mode','Normal','jumbo-normal'],['Jumbo card mode','Ranked','jumbo-ranked']].map(([format,rank,id])=>({format,rank,id}));
const state={view:'home',mode:'expanded-normal',cash:2500,walletCap:5000,inventory:{},deck:{},binder:[],sleeves:0,dividers:0,dice:0,coins:0,plushies:[],deckBox:false,logs:[],match:null,collectionFilter:'All',search:'',fridayVotes:0};
// Starter collection: a complete 150-card deck and all characters available for card review.
for(const c of cards){state.inventory[c.id]=c.kind==='Character'?5:(c.id==='energy'?50:c.id==='supporter'?15:5);}
state.deck={charlie:5,alastor:5,angel:5,vaggie:5,husk:5,niffty:5,blitzo:5,stolas:5,loona:5,moxxie:5,millie:5,dandy:5,astro:5,vee:5,pebble:5,zestial:5,energy:50,supporter:15,revive:5,effectcoin:5};
const fmt=()=>modes.find(m=>m.id===state.mode)||modes[0];
const escapeHtml=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const cardBy=id=>cards.find(c=>c.id===id);
const deckCount=()=>Object.values(state.deck).reduce((a,b)=>a+b,0);
const modeLabel=m=>`${m.format.replace(' format','')} · ${m.rank}`;
function updateHeader(){document.getElementById('cash').textContent=state.cash.toLocaleString();document.getElementById('activeFormat').textContent=modeLabel(fmt()).toUpperCase();document.querySelectorAll('.nav-item').forEach(n=>n.classList.toggle('active',n.dataset.view===state.view));}
function showToast(message){const t=document.getElementById('toast');t.textContent=message;t.classList.add('show');clearTimeout(showToast.timer);showToast.timer=setTimeout(()=>t.classList.remove('show'),2100)}
function navigate(view){state.view=view;render();window.scrollTo(0,0)}
function artMarkup(card){return `<div class="card-art" style="--c1:${card.colors[0]};--c2:${card.colors[1]}"><span class="card-rarity">${card.rarity}</span>${card.cost?`<span class="card-cost">${card.cost}</span>`:''}<span class="card-emoji">${card.emoji}</span></div>`}
function cardMarkup(card,qty=''){return `<article class="tcg-card" data-card="${card.id}" tabindex="0" role="button" aria-label="View ${escapeHtml(card.name)}">${artMarkup(card)}<div class="card-copy"><div class="card-name">${escapeHtml(card.name)}</div><div class="card-sub">${card.series} · ${card.kind}</div><div class="card-stats"><span>${card.hp?`♥ ${card.hp} HP`:card.kind.toUpperCase()}</span><span>${card.atk?`⚔ ${card.atk}`:'✦'}</span></div></div>${qty?`<span class="card-qty">×${qty}</span>`:''}</article>`}
function render(){updateHeader();const root=document.getElementById('mainContent');({home:renderHome,shop:renderShop,deck:renderDeck,collection:renderCollection,battle:renderBattle})[state.view]();bindCommon();}
function renderHome(){const active=fmt();document.getElementById('mainContent').innerHTML=`<section class="hero"><div class="hero-copy"><span class="eyebrow">A fan-made card battler</span><h1>Your collection.<br>Your afterlife.</h1><p>Build a 150-card deck, fill your bunker, and battle across three delightfully chaotic worlds.</p><button class="button primary" data-action="start-battle">Enter the arena <span>→</span></button></div><div class="hero-art" aria-hidden="true">😈</div></section>
 <div class="section-heading"><div><h2>Choose your game mode</h2><p>Pick a format and queue style. Your selection sets the current card format.</p></div><span class="tag">10 ways to play</span></div><section class="mode-grid">${modes.map(m=>`<button class="mode-card ${state.mode===m.id?'selected':''}" data-mode="${m.id}"><span class="mode-icon">${m.format.includes('Metal')?'◈':m.format.includes('Jumbo')?'▣':m.rank==='Ranked'?'♛':'✦'}</span><span class="mode-title">${m.format}</span><span class="mode-sub">${m.rank} queue · ${m.id.includes('metal')?'Metal cards':m.id.includes('jumbo')?'Jumbo cards':`${m.format.split(' ')[0]} card pool`}</span></button>`).join('')}</section>
