function renderCollection(){const filters=['All',"Hazbin Hotel",'Helluva Boss',"Dandy's World",'Energy','Trainer','Item'];const f=state.collectionFilter||'All';let found=cards.filter(c=>(f==='All'||c.series===f||c.kind===f)&&(!state.search||c.name.toLowerCase().includes(state.search.toLowerCase())));document.getElementById('mainContent').innerHTML=`<span class="eyebrow">Every card, one by one</span><h1 class="page-title">Card collection</h1><p class="page-intro">Tap any card to inspect its full effect and stats. Tell me how you want the cards changed.</p><div class="collection-toolbar"><div class="tabs" style="margin:0">${filters.map(x=>`<button class="tab ${f===x?'active':''}" data-filter="${x}">${x}</button>`).join('')}</div><input class="search" type="search" placeholder="Search cards…" value="${escapeHtml(state.search)}" aria-label="Search cards"></div><div class="section-heading"><div><h2>${found.length} cards in the set</h2><p>${Object.values(state.inventory).reduce((a,b)=>a+b,0)} cards owned · ${state.binder.length} cards in binder · tap to review</p></div><button class="button secondary small" data-action="binder">${state.binder.length?'View binder':'Open binder'}</button></div><section class="cards-grid">${found.map(c=>cardMarkup(c,state.inventory[c.id]||0)).join('')}</section>`;}
function currentDeck(){return state.deckMode==='quick'?state.quickDeck:state.deck;}
