function startSetup(){state.setup={stage:'rps',player:null,enemy:null};renderSetup();}
function renderSetup(){const s=state.setup;if(!s)return;if(s.stage==='rps'){openModal(`<span class="eyebrow">First decision</span><h2>Rock, paper, scissors</h2><p class="page-intro">Choose your move. The winner gets to call the coin toss.</p><div class="choice-row setup-choices">${['rock','paper','scissors'].map(x=>`<button class="button secondary setup-choice" data-rps="${x}">${({rock:'✊',paper:'✋',scissors:'✌️'})[x]} ${x}</button>`).join('')}</div>`);return;}if(s.stage==='coin'){if(s.winner==='opponent'){const choice=randomItem(['heads','tails']),flip=randomItem(['heads','tails']);state.setup.first=choice===flip?'opponent':'player';state.setup.flip=flip;finishSetup();return;}openModal(`<span class="eyebrow">You won the toss</span><h2>Call the coin</h2><p class="page-intro">Choose heads or tails. If your call matches, you go first.</p><div class="choice-row setup-choices"><button class="button gold" data-coin="heads">🪙 Heads</button><button class="button gold" data-coin="tails">🪙 Tails</button></div>`);}}
function finishSetup(){const d=currentDeck(),deck=[];Object.entries(d).forEach(([id,n])=>{for(let i=0;i<n;i++)deck.push(id);});shuffle(deck);const draw=()=>deck.length?deck.shift():randomItem(cards).id;const units=[];for(let i=0;i<5;i++){const lane=state.bunker[i]||[];const id=lane.find(x=>cardBy(x)?.kind==='Character')||cards.filter(c=>c.kind==='Character')[i].id;const c=cardBy(id);units.push({id,hp:c.hp,maxHp:c.hp,energy:0,status:[]});}const enemy=shuffle(cards.filter(c=>c.kind==='Character').slice()).slice(0,5).map(c=>({id:c.id,hp:c.hp,maxHp:c.hp,energy:0,status:[]}));const hand=Array.from({length:7},draw);const m=state.match={deck,hand,units,enemy,prizes:15,enemyPrizes:15,round:1,turn:state.setup.first||'player',selected:0,target:0,selectedHand:-1,usedEnergy:false,logs:[`Coin landed ${state.setup.flip||'in your favor'} — ${state.setup.first==='player'?'you':'the opponent'} go first.`],diceBonus:0};state.setup=null;closeModal();navigate('battle');if(m.turn==='opponent')enemyTurn();}
function finishMatch(winner){const m=state.match;if(!m||m.finished)return;m.finished=true;m.logs.unshift(winner==='player'?'Victory! You claimed the arena.':'Defeat. Regroup and try another match.');if(winner==='player')addCash(150);render();showToast(winner==='player'?'Victory reward: ◈ 150':'Match over');}
function checkMatch(){const m=state.match;if(!m)return;if(m.prizes<=0||m.units.every(u=>u.hp<=0))finishMatch('enemy');else if(m.enemyPrizes<=0||m.enemy.every(u=>u.hp<=0))finishMatch('player');}
function drawCard(m){if(m.deck.length)m.hand.push(m.deck.shift());else m.logs.push('Your deck is empty.');}
function applyDamage(unit,amount){unit.hp=Math.max(0,unit.hp-amount);if(unit.hp===0){const m=state.match;m.logs.push(`${cardBy(unit.id)?.name||'Character'} was knocked out.`);if(m.units.includes(unit))m.prizes=Math.max(0,m.prizes-1);else m.enemyPrizes=Math.max(0,m.enemyPrizes-1);}}
function attack(){const m=state.match;if(!m||m.finished||m.turn!=='player')return;const attacker=m.units[m.selected],defender=m.enemy[m.target];if(!attacker||attacker.hp<=0||!defender||defender.hp<=0){showToast('Choose a living character and target.');return;}const c=cardBy(attacker.id);if(attacker.energy<c.cost){showToast(`Attach ${c.cost-attacker.energy} more energy to attack.`);return;}let dmg=c.atk+(m.diceBonus||0);m.diceBonus=0;if(c.id==='blitzo'&&m.units.filter(u=>u.hp>0).length>1)dmg+=20;if(c.id==='millie'){const other=m.enemy.find((u,i)=>i!==m.target&&u.hp>0);if(other)applyDamage(other,10);}if(c.id==='charlie')m.units.forEach(u=>{if(u.hp>0)u.hp=Math.min(u.maxHp,u.hp+20);});if(c.id==='husk'&&Math.random()<.5)drawCard(m);m.logs.unshift(`${c.name} dealt ${dmg} damage to ${cardBy(defender.id).name}.`);applyDamage(defender,dmg);attacker.status=attacker.status.filter(x=>x!=='Drowsy');m.turn='opponent';m.usedEnergy=false;m.selectedHand=-1;checkMatch();render();if(!m.finished)enemyTurn();}
function enemyTurn(){const m=state.match;if(!m||m.finished)return;m.turn='opponent';const living=m.enemy.filter(u=>u.hp>0);if(!living.length){checkMatch();return;}const attacker=living[0],target=randomItem(m.units.filter(u=>u.hp>0));if(!target){checkMatch();return;}attacker.energy++;const c=cardBy(attacker.id);if(attacker.energy>=c.cost){const dmg=c.atk;m.logs.unshift(`Opponent’s ${c.name} dealt ${dmg} damage to ${cardBy(target.id).name}.`);applyDamage(target,dmg);attacker.energy=0;}else m.logs.unshift(`Opponent attached energy to ${c.name}.`);drawCard(m);m.round++;m.turn='player';m.usedEnergy=false;if(m.units[m.selected]?.hp<=0){const next=m.units.findIndex(u=>u.hp>0);m.selected=next<0?0:next;}checkMatch();render();}
function endTurn(){const m=state.match;if(!m||m.finished||m.turn!=='player')return;m.logs.unshift('You ended your turn.');m.turn='opponent';enemyTurn();}
function playSupporter(){const m=state.match;if(!m||m.turn!=='player')return;const i=m.hand.findIndex(id=>cardBy(id)?.kind==='Supporter');if(i<0){showToast('No supporter in your hand.');return;}m.hand.splice(i,1);drawCard(m);drawCard(m);m.logs.unshift('Strategic Support: drew 2 cards.');render();}
function attachEnergy(){const m=state.match;if(!m||m.turn!=='player'||m.usedEnergy)return;const i=m.hand.findIndex(id=>cardBy(id)?.kind==='Energy');if(i<0){showToast('No energy in your hand.');return;}const unit=m.units[m.selected];if(!unit||unit.hp<=0){showToast('Select a living character first.');return;}m.hand.splice(i,1);unit.energy++;m.usedEnergy=true;m.logs.unshift(`Attached energy to ${cardBy(unit.id).name}.`);render();}
function rollDice(){const m=state.match;if(!m)return;const roll=1+Math.floor(Math.random()*6);m.diceBonus=roll*10;m.logs.unshift(`Battle dice: ${roll} — next attack gets +${m.diceBonus} damage.`);render();}

