function rollDice(){const m=state.match;if(!m)return;if(!state.dice){showToast('Buy a Battle Dice Set first.');return;}const roll=1+Math.floor(Math.random()*6);m.diceBonus=roll*10;m.logs.unshift(`Battle dice: ${roll} — next attack gets +${m.diceBonus} damage.`);render();}
function changeDeck(id,delta){const d=currentDeck(),c=cardBy(id),next=(d[id]||0)+delta,total=Object.values(d).reduce((a,b)=>a+b,0);if(next<0)return;if(delta>0&&total>=deckTarget()){showToast(`This deck holds ${deckTarget()} cards.`);return;}if(delta>0&&c.kind==='Character'&&next>5){showToast('Characters are limited to 5 copies.');return;}if(delta>0&&next>(state.inventory[id]||0)){showToast(`You only own ${state.inventory[id]||0} ${c.name} cards.`);return;}d[id]=next;render();}
function validateDeck(){const d=currentDeck(),count=Object.values(d).reduce((a,b)=>a+b,0),characterCount=cards.filter(c=>c.kind==='Character').reduce((n,c)=>n+(d[c.id]||0),0);if(count!==deckTarget()){showToast(`Your deck needs exactly ${deckTarget()} cards (currently ${count}).`);return;}if(!characterCount){showToast('Add at least one character to your deck.');return;}showToast('Deck validated — ready for the arena!');state.view='battle';render();}
function bindCommon(){document.body.onclick=e=>{const target=e.target.closest('button,[data-card]');if(!target)return;
 if(target.dataset.view){navigate(target.dataset.view);return;}if(target.dataset.mode){state.mode=target.dataset.mode;render();return;}if(target.dataset.action){const a=target.dataset.action;if(a==='start-battle')startSetup();else if(a==='binder')showBinder();else if(a==='friday'){showBinder();}else if(a==='validate-deck')validateDeck();else if(a==='sell-extras')sellExtra();else if(a==='attach-energy')attachEnergy();else if(a==='play-supporter')playSupporter();else if(a==='attack')attack();else if(a==='end-turn')endTurn();else if(a==='battle-dice')rollDice();else if(a==='surrender'){state.match=null;showToast('You left the arena.');render();}else if(a==='vote-friday'){if(state.votedFriday)showToast('You already voted in this week’s showcase.');else{state.votedFriday=true;state.fridayVotes++;showToast('Vote cast — thanks for showing up!');showBinder();}}return;}
 if(target.dataset.buy){buyProduct(target.dataset.buy);return;}if(target.dataset.shopStamp){shopStamp=target.dataset.shopStamp==='on';if(!shopStamp)shopSigned=false;render();return;}if(target.dataset.shopSigned){shopSigned=!shopSigned;render();return;}if(target.dataset.shopCat){state.shopCat=target.dataset.shopCat;render();return;}if(target.dataset.filter){state.collectionFilter=target.dataset.filter;render();return;}if(target.dataset.deckMode){state.deckMode=target.dataset.deckMode;render();return;}if(target.dataset.deckChange){changeDeck(target.dataset.cardId,Number(target.dataset.deckChange));return;}if(target.dataset.clearBunker!==undefined){state.bunker[Number(target.dataset.clearBunker)]=[];render();return;}if(target.dataset.card){inspectCard(target.dataset.card);return;}if(target.dataset.playerUnit!==undefined){const i=Number(target.dataset.playerUnit);if(state.match?.units[i]?.hp>0){state.match.selected=i;render();}return;}if(target.dataset.enemyUnit!==undefined){const i=Number(target.dataset.enemyUnit);if(state.match?.enemy[i]?.hp>0){state.match.target=i;render();}return;}if(target.dataset.handCard!==undefined){const m=state.match;if(!m)return;const i=Number(target.dataset.handCard),id=m.hand[i],c=cardBy(id);if(c?.kind==='Character'){const empty=m.units.findIndex(u=>u.hp<=0);if(empty<0){showToast('Your bunker has no open slot.');return;}m.units[empty]={id,hp:c.hp,maxHp:c.hp,energy:0,status:[]};m.hand.splice(i,1);m.logs.unshift(`${c.name} joined your bunker.`);render();}else if(c?.kind==='Revive'){const unit=m.units.find(u=>u.hp<=0);if(!unit){showToast('No character needs reviving.');return;}unit.hp=30;m.hand.splice(i,1);m.logs.unshift(`${cardBy(unit.id).name} returned with 30 HP.`);render();}else{m.selectedHand=i;render();}return;}
 if(target.dataset.rps){const user=target.dataset.rps,bot=randomItem(['rock','paper','scissors']);state.setup.player=user;state.setup.enemy=bot;const result=user===bot?'tie':({rock:'scissors',paper:'rock',scissors:'paper'})[user]===bot?'player':'opponent';if(result==='tie'){showToast(`Both chose ${user}; try again.`);state.setup={stage:'rps'};renderSetup();}else{state.setup.stage='coin';state.setup.winner=result;showToast(`You: ${user} · Opponent: ${bot} — ${result==='player'?'you win':'opponent wins'}!`);renderSetup();}return;}if(target.dataset.coin){const flip=randomItem(['heads','tails']);state.setup.flip=flip;state.setup.first=target.dataset.coin===flip?'player':'opponent';showToast(`Coin: ${flip}. ${state.setup.first==='player'?'You go first!':'Opponent goes first.'}`);finishSetup();return;}
 if(target.dataset.binderToggle){const id=target.dataset.binderToggle;if(state.binder.includes(id))state.binder=state.binder.filter(x=>x!==id);else if((state.inventory[id]||0)>0)state.binder.push(id);else{showToast('You need to own a copy before adding it.');return;}inspectCard(id);return;}
