/* Battle table, cards, and touch-friendly overlays */
.eyebrow{display:block;color:var(--red);font-size:10px;font-weight:800;letter-spacing:.14em;text-transform:uppercase;margin:5px 0 8px}
.page-title{font:700 36px 'Space Grotesk',sans-serif;letter-spacing:-.04em;margin:0 0 7px}
.page-intro{color:var(--muted);font-size:14px;line-height:1.55;margin:0 0 22px;max-width:760px}
.section-heading{display:flex;align-items:end;justify-content:space-between;gap:16px;margin:34px 0 15px}
.section-heading h2{font:600 21px 'Space Grotesk',sans-serif;margin:0 0 5px}
.section-heading p{color:var(--muted);font-size:12px;margin:0}
.box,.board{background:linear-gradient(145deg,#1d1828,#17131f);border:1px solid var(--line);border-radius:var(--radius);padding:20px}
.box h3{font:600 17px 'Space Grotesk',sans-serif;margin:0 0 12px}
.row,.choice-row,.tabs,.counter{display:flex;align-items:center;gap:9px;flex-wrap:wrap}
.choice-row{margin:12px 0 18px}
.button,.choice,.tab{border:1px solid var(--line);border-radius:12px;background:#ffffff08;padding:10px 14px;font-weight:700;transition:.18s ease}
.button:hover,.choice:hover,.tab:hover{transform:translateY(-1px);border-color:#ffffff48}
.button.primary{background:linear-gradient(130deg,#ff647b,#d94676);border:0;color:white;box-shadow:0 7px 22px #ff4e7028}
.button.secondary{background:#ffffff08}
.button.gold{background:linear-gradient(130deg,#ffcf7e,#e9a953);border:0;color:#261a24}
.button.small{padding:8px 11px;font-size:11px;border-radius:10px}
.button:disabled{opacity:.42;cursor:not-allowed;transform:none}
.text-button{border:0;background:none;color:var(--red);font-weight:700;font-size:12px}
.choice{color:var(--muted);font-size:12px}.choice.selected,.tab.active{color:var(--text);border-color:#ff7187;background:#ff4e701b}
.tabs{margin:18px 0;gap:6px}.tab{padding:8px 12px;font-size:11px;color:var(--muted)}
.tag,.shop-category{display:inline-flex;align-items:center;border:1px solid #ffffff1a;border-radius:999px;padding:5px 9px;color:var(--muted);font-size:10px;font-weight:700}
.mode-grid{display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:12px}
.mode-card{display:flex;flex-direction:column;align-items:flex-start;text-align:left;gap:6px;min-height:120px;padding:16px;border:1px solid var(--line);border-radius:15px;background:linear-gradient(145deg,#211b2c,#191522)}
.mode-card.selected{border-color:var(--red);box-shadow:inset 0 0 0 1px #ff4e7055,0 8px 24px #ff4e7013}
