const modalRoot=document.getElementById('modalRoot');
const randomItem=list=>list[Math.floor(Math.random()*list.length)];
const shuffle=list=>{for(let i=list.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[list[i],list[j]]=[list[j],list[i]];}return list;};
function giveCard(id,qty=1){state.inventory[id]=(state.inventory[id]||0)+qty;}
function addCash(amount){state.cash=Math.min(state.walletCap,state.cash+amount);}
function openModal(html){modalRoot.innerHTML=`<div class="modal-backdrop" data-close-modal><section class="modal" role="dialog" aria-modal="true">${html}</section></div>`;}
function closeModal(){modalRoot.innerHTML='';}
function inspectCard(id){const c=cardBy(id);if(!c)return;const inBinder=state.binder.includes(id);openModal(`<button class="modal-close" data-close-modal aria-label="Close">×</button><div class="card-detail">${artMarkup(c)}<div class="detail-text"><span class="eyebrow">${escapeHtml(c.series)} · ${c.rarity}</span><h2>${escapeHtml(c.name)}</h2><p>${escapeHtml(c.text)}</p><div class="deck-row"><span>Type</span><b>${c.kind}</b></div>${c.hp?`<div class="deck-row"><span>Health</span><b>${c.hp} HP</b></div>`:''}${c.atk?`<div class="deck-row"><span>Attack</span><b>${c.atk} damage · ${c.cost} energy</b></div>`:''}<div class="deck-row"><span>You own</span><b>${state.inventory[id]||0}</b></div><div class="choice-row"><button class="button ${inBinder?'secondary':'primary'}" data-binder-toggle="${id}">${inBinder?'Remove from binder':'Add to binder'}</button><button class="button secondary" data-close-modal>Done</button></div></div></div>`);}
function showBinder(){const owned=state.binder.filter(id=>(state.inventory[id]||0)>0);openModal(`<button class="modal-close" data-close-modal aria-label="Close">×</button><span class="eyebrow">Friday collection contest</span><h2>Collector binder</h2><p class="page-intro">${owned.length} card${owned.length===1?'':'s'} in your showcase. Visit Cards and tap any owned card to add it.</p><div class="cards-grid binder-grid">${owned.map(id=>cardMarkup(cardBy(id),state.inventory[id])).join('')||'<p class="empty-state">Your binder is waiting for its first card.</p>'}</div><div class="friday-banner"><div><b>Friday showcase</b><p>Cast a vote for this week’s favorite collection.</p></div><button class="button gold" data-action="vote-friday">Vote · ${state.fridayVotes}</button></div><div class="choice-row"><button class="button secondary" data-close-modal>Close binder</button></div>`);}
